const s2_uds_module_t *s2_uds_module_by_resp(uint32_t can_id)
{
    for (size_t i = 0; i < s2_uds_module_count; i++) {
        if (s2_uds_modules[i].resp_id == can_id) {
            return &s2_uds_modules[i];
        }
    }
    return NULL;
}

const s2_uds_did_t *s2_uds_find_did(uint8_t module, uint16_t did)
{
    for (size_t i = 0; i < s2_uds_did_count; i++) {
        if (s2_uds_dids[i].module == module && s2_uds_dids[i].did == did) {
            return &s2_uds_dids[i];
        }
    }
    return NULL;
}

